"""This file contains the Sim Dialogs Mv Panel Lat Pos, Mv Panel Long Pos and Mv DCB Page Object class for the
SIM MV PANEL LAT POS, SIM MV PANEL LONG POS and SIM MV DCB panes in the Sim Dialogs XVI test tool"""

import logging
from . import SimDialogs
from .. interactions import SimDialogMvLatFuncs
from .. interactions import SimDialogMvLongFuncs
from .. interactions import SimDialogMvDcbFuncs


logger = logging.getLogger(__name__)

class SimDialogsMvPanes(SimDialogs):
    ''' Page Object class for the SIM MV PANEL LAT POS, SIM MV PANEL LONG POS and SIM MV DCB panes'''

    def __init__(self, host_address: str ="192.168.30.4") -> None:
        super().__init__(host_address)

    #-------------------------------------- SIM MV PANEL LAT POS Pane --------------------------------------

    def toggle_sim_mv_panel_lat_pos_node_online_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Node Online checkbox in the Sim MV Panel Lat Pos Pane to either
        checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogMvLatFuncs.check_sim_mv_panel_lat_pos_node_online_checkbox()
        else:
            SimDialogMvLatFuncs.uncheck_sim_mv_panel_lat_pos_node_online_checkbox()

    def toggle_sim_mv_panel_lat_pos_auto_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Auto checkbox in the Sim MV Panel Lat Pos Pane to either
        checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogMvLatFuncs.check_sim_mv_panel_lat_pos_auto_checkbox()
        else:
            SimDialogMvLatFuncs.uncheck_sim_mv_panel_lat_pos_auto_checkbox()

    def read_sim_mv_panel_lateral_position_field(self) -> str:
        '''
        Gets the mv lateral position field value and returns it if found.

        Returns:
            str or None: Sim MV lateral position value'''
        return SimDialogMvLatFuncs.get_sim_mv_panel_lateral_position_textfield()

    def set_sim_mv_panel_lateral_position_field(self, value_to_set) -> None:
        '''
        Sets the mv lateral position field value to the specified value

        Args:
            value_to_set (str): Numeric value as a string for lateral position
        '''
        SimDialogMvLatFuncs.edit_sim_mv_panel_lateral_position_textfield(value_to_set)

    #-------------------------------------- SIM MV PANEL LONG POS Pane --------------------------------------

    def toggle_sim_mv_panel_long_pos_node_online_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Node Online checkbox in the Sim MV Panel Long Pos Pane to either
        checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogMvLongFuncs.check_sim_mv_panel_long_pos_node_online_checkbox()
        else:
            SimDialogMvLongFuncs.uncheck_sim_mv_panel_long_pos_node_online_checkbox()

    def toggle_sim_mv_panel_long_pos_auto_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Auto checkbox in the Sim MV Panel Long Pos Pane to either
        checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogMvLongFuncs.check_sim_mv_panel_long_pos_auto_checkbox()
        else:
            SimDialogMvLongFuncs.uncheck_sim_mv_panel_long_pos_auto_checkbox()

    def read_sim_mv_panel_longitudinal_position_field(self) -> str:
        '''
        Gets the mv longitudinal position field value and returns it if found.

        Returns:
            str or None: Sim MV longitudinal position value'''
        return SimDialogMvLongFuncs.get_sim_mv_panel_longitudinal_position_textfield()

    def set_sim_mv_panel_longitudinal_position_field(self, value_to_set) -> None:
        '''
        Sets the mv longitudinal position field value to the specified value

        Args:
            value_to_set (str): Numeric value as a string for longitudinal position
        '''
        SimDialogMvLongFuncs.edit_sim_mv_panel_longitudinal_position_textfield(value_to_set)

    #-------------------------------------- SIM MV DCB Pane --------------------------------------

    def toggle_sim_mv_dcb_online_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Online checkbox in the Sim MV DCB Pane to either
        checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogMvDcbFuncs.check_sim_mv_dcb_online_checkbox()
        else:
            SimDialogMvDcbFuncs.uncheck_sim_mv_dcb_online_checkbox()

    def toggle_sim_mv_dcb_beam_on_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Beam On checkbox in the Sim MV DCB Pane to either
        checked or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            SimDialogMvDcbFuncs.check_sim_mv_dcb_beam_on_checkbox()
        else:
            SimDialogMvDcbFuncs.uncheck_sim_mv_dcb_beam_on_checkbox()
